custom.rulesPlaceholder:
(event, helpers) => {
  // 工作日 9:00-17:00 屏蔽 YouTube Shorts 页面。
  const yt = helpers.getDomainHelper().youtube();

  function maybeBlock(ev) {
    if (!yt.isShortUrl(ev.url)) return;
    if (["Saturday", "Sunday"].includes(ev.time.dayName)) return;
    if (ev.time.hour < 9 || ev.time.hour >= 17) return;
    ev.setRedirectLink("https://example.com/focus");
    ev.preventDefault();
    ev.setResult(-1);
  }

  event.registerOpenWebEvent("shorts-block", maybeBlock, { priority: 10 });
  event.registerSwitchWebEvent("shorts-block", maybeBlock, { priority: 10 });
}

